270:   }).join('');
271:   return `
272:     <section class="hub-panel">
273:       <div class="panel-head">
274:         <div><p class="eyebrow">PERMANENT RECORD</p><h2>Hunter’s License</h2><p>Promotion is earned by clearing floors, felling guardians, and honoring contracts.</p></div>
275:         <span class="head-mark">♛</span>
276:       </div>
277:       <div class="license-panel-grid">
