302: function equipmentCard(slot, item, unlocked, equipped, level) {
303:   const levelCap = 5;
304:   const cost = Math.round(45 * level * level);
305:   const lockText = `Unlock · ${item.unlock} ✧`;
306:   const stats = slot === 'weapon'
307:     ? `<span>DMG <b>${Math.round(item.damage * (1 + (level - 1) * 0.12))}</b></span><span>SPEED <b>${item.cooldown.toFixed(2)}s</b></span><span>REACH <b>${item.range}</b></span><span>CRIT <b>${Math.round(item.crit * 100)}%</b></span>`
308:     : slot === 'armor'
309:       ? `<span>HP <b>+${Math.round(item.hp * (1 + (level - 1) * 0.1))}</b></span><span>AETHER <b>+${item.aether}</b></span><span>DR <b>${Math.round(item.dr * 100)}%</b></span>`
310:       : `<span>PASSIVE</span>`;
311:   return `<div class="forge-card ${equipped ? 'equipped' : ''} ${unlocked ? '' : 'locked'}">
312:     <div class="forge-card-top">
313:       <div class="forge-icon">${item.icon}</div>
314:       <div class="forge-level">${unlocked ? `LV. ${level} / ${levelCap}` : 'UNFORGED'}</div>
315:     </div>
316:     <h4>${item.name}</h4>
317:     <p>${item.desc}</p>
318:     <div class="forge-stats">${stats}</div>
319:     <div class="forge-actions">
320:       ${unlocked
321:         ? `${equipped ? '<button class="tiny-button" disabled>Equipped</button>' : `<button class="tiny-button primary" data-action="forge-equip" data-slot="${slot}" data-id="${item.id}">Equip</button>`}
322:            ${slot !== 'charm' || true ? `<button class="tiny-button" data-action="forge-upgrade" data-id="${item.id}" ${level >= levelCap ? 'disabled' : ''}>${level >= levelCap ? 'Max level' : `Upgrade · ${cost} ✧`}</button>` : ''}`
323:         : `<button class="tiny-button primary" data-action="forge-unlock" data-slot="${slot}" data-id="${item.id}">${lockText}</button>`}
324:     </div>
325:   </div>`;
326: }
