328: function renderForge() {
329:   const save = game.save;
330:   const weaponCards = Object.values(WEAPONS).map(item => equipmentCard('weapon', item, save.unlocked.weapons.includes(item.id), save.equipment.weapon === item.id, save.equipment.levels[item.id] || 1)).join('');
331:   const armorCards = Object.values(ARMORS).map(item => equipmentCard('armor', item, save.unlocked.armors.includes(item.id), save.equipment.armor === item.id, save.equipment.levels[item.id] || 1)).join('');
332:   const charmCards = Object.values(CHARMS).map(item => equipmentCard('charm', item, save.unlocked.charms.includes(item.id), save.equipment.charm === item.id, 1)).join('');
333:   const metaCards = Object.values(META_UPGRADES).map(u => {
334:     const level = save.meta[u.id] || 0;
335:     const cost = u.cost + level * u.step;
336:     return `<div class="forge-card ${level >= u.max ? 'equipped' : ''}">
337:       <div class="forge-card-top"><div class="forge-icon">${u.icon}</div><div class="forge-level">LV. ${level} / ${u.max}</div></div>
338:       <h4>${u.name}</h4><p>${u.desc}</p>
339:       <div class="forge-stats"><span>PERMANENT</span><span>APPLIED <b>${level * (u.id === 'might' ? 6 : u.id === 'vitality' ? 14 : u.id === 'agility' ? 4 : u.id === 'aether' ? 12 : 8)}${u.id === 'might' || u.id === 'agility' || u.id === 'fortune' ? '%' : ''}</b></span></div>
340:       <div class="forge-actions"><button class="tiny-button ${level < u.max ? 'primary' : ''}" data-action="meta-upgrade" data-id="${u.id}" ${level >= u.max ? 'disabled' : ''}>${level >= u.max ? 'Max' : `Forge · ${cost} ✧`}</button></div>
341:     </div>`;
342:   }).join('');
343:   return `
344:     <section class="hub-panel">
345:       <div class="panel-head">
346:         <div><p class="eyebrow">THE LOW WARD FORGE</p><h2>Equipment & Permanence</h2><p>Spend aether shards to unlock armaments, raise their levels, and sharpen Lyra’s body for every future ascent.</p></div>
347:         <span class="head-mark">⚒</span>
348:       </div>
349:       <div class="section-label">ATTRIBUTES · PERMANENT</div>
350:       <div class="forge-grid">${metaCards}</div>
351:       <div class="section-label">WEAPONS</div>
352:       <div class="forge-grid">${weaponCards}</div>
353:       <div class="section-label">ARMOR</div>
354:       <div class="forge-grid">${armorCards}</div>
355:       <div class="section-label">CHARMS</div>
356:       <div class="forge-grid">${charmCards}</div>
357:     </section>`;
358: }
