360: function renderContracts() {
361:   const cards = game.save.contracts.map(c => {
362:     const p = contractProgress(game.save, c);
363:     const pct = clamp(p.value / p.target, 0, 1) * 100;
364:     return `<div class="contract-card ${p.complete ? 'complete' : ''}">
365:       <div class="contract-icon">✦</div>
366:       <div>
367:         <h4>${c.title}</h4>
368:         <p>${p.label} ${c.unit}${c.absolute ? ' reached' : ''} · Progress survives death.</p>
369:         <div class="contract-bar ${p.complete ? 'complete' : ''}"><div style="width:${pct}%"></div></div>
370:       </div>
371:       <div class="contract-reward">
372:         <span>REWARD</span>
373:         <b>${c.rewardShards} ✧ · ${c.rewardXp} XP</b>
374:         <button class="tiny-button ${p.complete ? 'primary' : ''}" data-action="claim-contract" data-id="${c.id}" ${p.complete ? '' : 'disabled'}>${p.complete ? 'Claim' : 'In progress'}</button>
375:       </div>
376:     </div>`;
377:   }).join('');
378:   return `
379:     <section class="hub-panel">
380:       <div class="panel-head">
381:         <div><p class="eyebrow">THE POSTING WALL</p><h2>Hunter Contracts</h2><p>Three standing contracts. Progress is recorded from the moment each is accepted and never expires.</p></div>
382:         <span class="head-mark">✎</span>
383:       </div>
384:       <div class="contract-list">${cards || '<div class="contract-empty">No contracts posted. Return after your next ascent.</div>'}</div>
385:       <div class="lore-strip">“The guild does not ask why you climb. It asks only what you brought back.”</div>
386:     </section>`;
387: }
