389: function renderCodex() {
390:   const tabs = [['loop', 'Core Loop'], ['progression', 'Progression'], ['quests', 'Contracts'], ['bestiary', 'Bestiary']];
391:   const tabHtml = tabs.map(([id, label]) => `<button data-codex="${id}" class="${game.codexTab === id ? 'active' : ''}">${label}</button>`).join('');
392:   let body = '';
393:   if (game.codexTab === 'bestiary') {
394:     body = `<div class="bestiary-grid">${Object.values(ENEMY_INFO).map(e => `
395:       <div class="bestiary-card">
396:         <div class="bestiary-top"><div class="bestiary-icon">${e.icon}</div><div><h4>${e.name}</h4><span>${e.role} · ${e.threat}</span></div></div>
397:         <p>${e.desc}</p>
398:         <div class="bestiary-tell"><b>TELL</b> · ${e.tell}</div>
399:       </div>`).join('')}</div>`;
400:   } else {
401:     body = `<div class="codex-grid">${(CODEX_DATA[game.codexTab] || []).map(entry => `
402:       <div class="codex-entry"><h3>${entry.title}</h3><p>${entry.body}</p></div>`).join('')}</div>`;
403:   }
404:   return `
405:     <section class="hub-panel">
406:       <div class="panel-head">
407:         <div><p class="eyebrow">FIELD MANUAL</p><h2>The Hunter’s Codex</h2><p>The design of the tower, written in the margins of a dead hunter’s journal.</p></div>
