439: function computeStats(boons = {}) {
440:   const save = game.save;
441:   const weapon = WEAPONS[save.equipment.weapon] || WEAPONS.saber;
442:   const armor = ARMORS[save.equipment.armor] || ARMORS.coat;
443:   const charm = save.equipment.charm ? CHARMS[save.equipment.charm] : null;
444:   const wl = save.equipment.levels[weapon.id] || 1;
445:   const al = save.equipment.levels[armor.id] || 1;
446:   const rankIndex = rankIndexForXp(save.licenseXp);
447:   const b = id => boons[id] || 0;
448:   const attackSpeed = 1 + b('quickening') * 0.1;
449:   const damage = weapon.damage * (1 + (wl - 1) * 0.12) * (1 + save.meta.might * 0.06)
450:     * (1 + rankIndex * 0.04) * (1 + (charm?.effect?.damage || 0)) * (1 + b('bloodEdge') * 0.15);
451:   return {
452:     weapon,
453:     armor,
454:     charm,
455:     damage,
456:     cooldown: weapon.cooldown / attackSpeed,
457:     range: weapon.range,
458:     arc: weapon.arc,
459:     crit: clamp(weapon.crit + (charm?.effect?.crit || 0) + b('eagleEye') * 0.08, 0, 0.75),
460:     lifesteal: b('leech') * 0.03,
461:     maxHp: Math.round(100 + armor.hp * (1 + (al - 1) * 0.1) + save.meta.vitality * 14 + b('ironSkin') * 20),
462:     maxAether: Math.round(55 + armor.aether * (1 + (al - 1) * 0.1) + save.meta.aether * 12 + b('aetherWell') * 22),
463:     speed: 260 * armor.speed * (1 + save.meta.agility * 0.04) * (1 + b('fleetFoot') * 0.08),
464:     dr: clamp(armor.dr + b('serenity') * 0.08, 0, 0.5),
465:     shardMult: (1 + rankIndex * 0.05) * (1 + save.meta.fortune * 0.08) * (1 + b('greed') * 0.2),
466:     regen: 1.9 + b('aetherWell') * 0.8,
467:     specialMult: 1 + b('arcaneSurge') * 0.28,
468:     dashCooldown: 1.15 * (1 - b('blinkStep') * 0.18) * (1 - (charm?.effect?.dash || 0)),
469:     roomHeal: charm?.effect?.roomHeal || 0,
470:     executioner: b('executioner') > 0 ? 1 + b('executioner') * 0.3 : 1,
471:     shield: 0
472:   };
473: }
