564:     const inward = entrySide === 'n' ? { x: 0, y: 1 } : entrySide === 's' ? { x: 0, y: -1 }
565:       : entrySide === 'w' ? { x: 1, y: 0 } : { x: -1, y: 0 };
566:     p.x = clamp(c.x + inward.x * 118, WALL + 55, ROOM_W - WALL - 55);
567:     p.y = clamp(c.y + inward.y * 118, WALL + 55, ROOM_H - WALL - 55);
568:     p.facing = Math.atan2(inward.y, inward.x);
569:   } else {
570:     p.x = ROOM_W / 2;
571:     p.y = ROOM_H * 0.68;
572:     p.facing = -Math.PI / 2;
573:   }
