623: function randomSpawnPoint(minFromPlayer = 250) {
624:   const p = game.player;
625:   for (let i = 0; i < 90; i++) {
626:     const x = WALL + 130 + Math.random() * (ROOM_W - WALL * 2 - 260);
627:     const y = WALL + 130 + Math.random() * (ROOM_H - WALL * 2 - 260);
628:     if (Math.hypot(x - p.x, y - p.y) < minFromPlayer) continue;
629:     if (game.room.obstacles.some(o => Math.hypot(x - o.x, y - o.y) < o.r + 48)) continue;
630:     return { x, y };
631:   }
632:   return { x: ROOM_W / 2 + rand(-220, 220), y: ROOM_H / 2 + rand(-160, 160) };
633: }
