635: function enemyPool(floor) {
636:   if (floor <= 1) return ['wisp', 'hound'];
637:   if (floor <= 2) return ['wisp', 'hound', 'moth'];
638:   if (floor <= 3) return ['hound', 'knight', 'wisp', 'moth'];
639:   if (floor <= 5) return ['hound', 'knight', 'wraith', 'moth'];
640:   if (floor <= 7) return ['knight', 'wraith', 'sentinel', 'wisp'];
641:   if (floor <= 10) return ['wraith', 'sentinel', 'knight', 'moth'];
642:   return ['wraith', 'sentinel', 'knight', 'moth'];
643: }
