665:     id: `${type}-${Math.random().toString(36).slice(2, 8)}`,
666:     type,
667:     name: base.name,
668:     x, y,
669:     r: base.r * (elite ? 1.16 : 1),
670:     hp: Math.round(base.hp * scale * eliteScale),
671:     maxHp: Math.round(base.hp * scale * eliteScale),
672:     speed: base.speed * (1 + (floor - 1) * 0.018) * (elite ? 1.08 : 1),
673:     damage: base.damage * (1 + (floor - 1) * 0.07) * (elite ? 1.35 : 1),
674:     elite,
675:     state: 'chase',
676:     stateTimer: 0,
677:     attackTimer: 0.7 + Math.random() * 1.4,
678:     attackIndex: 0,
679:     pending: null,
