691: function spawnWave(room) {
692:   const floor = game.floor;
693:   const pool = enemyPool(floor);
694:   const count = Math.min(9, 3 + Math.floor(floor * 0.42) + Math.floor(Math.random() * 2));
695:   const eliteChance = floor >= 5 ? Math.min(0.26, (floor - 4) * 0.035) : 0;
696:   for (let i = 0; i < count; i++) {
697:     const pos = randomSpawnPoint(240);
698:     const type = pool[(i + Math.floor(Math.random() * pool.length)) % pool.length];
699:     const elite = Math.random() < eliteChance && i > 0;
700:     const e = createEnemy(type, pos.x, pos.y, floor, elite);
701:     game.enemies.push(e);
702:     if (elite) {
703:       e.hp = Math.round(e.hp * 1.12);
704:       e.maxHp = e.hp;
705:     }
706:   }
