772: function getInteractable() {
773:   const room = game.room;
774:   if (!room || game.mode !== 'playing') return null;
775:   const p = game.player;
776:   if (room.type === 'treasure' && !room.chestOpened) {
777:     if (dist(p, chestPosition(room)) < 112) return { kind: 'chest', label: 'Open the sealed hoard' };
778:   }
779:   if (room.type === 'shrine' && !room.shrineUsed) {
780:     if (dist(p, shrinePosition(room)) < 112) return { kind: 'shrine', label: 'Touch the aether shrine' };
781:   }
782:   if (room.type === 'exit' || room.type === 'boss') {
783:     if (dist(p, portalPosition(room)) < 125) {
784:       if (game.run.sealBroken) return { kind: 'portal', label: game.floor >= MAX_FLOOR ? 'Claim the hollow crown' : 'Descend to the next floor' };
785:       return { kind: 'locked', label: `Seal the floor — ${game.run.roomsCleared} / ${game.floorData.required} halls` };
786:     }
787:   }
788:   return null;
789: }
