791: function doInteract() {
792:   if (game.mode !== 'playing' || !game.player) return;
793:   const target = getInteractable();
794:   if (!target) return;
795:   if (target.kind === 'locked') {
796:     game.audio.play('error');
797:     toast('The stair gate is sealed. Clear every hostile hall.', 'danger', '◇');
798:     return;
799:   }
800:   if (target.kind === 'chest') {
801:     const room = game.room;
802:     room.chestOpened = true;
803:     game.audio.play('chest');
804:     const value = grantShards(28 + game.floor * 9, true);
805:     toast(`The hoard yields <b>${value}</b> aether shards`, '', '✧');
806:     burst(chestPosition(room).x, chestPosition(room).y, 34, '#ffdb99', 190);
807:     game.pendingBoon = { reason: 'hoard' };
808:     setTimeout(() => { if (game.mode === 'playing') offerBoons('THE HOARD OPENS'); }, 450);
809:     markSave();
810:     return;
811:   }
812:   if (target.kind === 'shrine') {
813:     const room = game.room;
814:     room.shrineUsed = true;
815:     const heal = Math.round(game.player.maxHp * 0.35);
816:     game.player.hp = Math.min(game.player.maxHp, game.player.hp + heal);
817:     game.player.aether = game.player.maxAether;
818:     game.audio.play('shrine');
819:     toast(`The shrine restores <b>${heal}</b> health and all aether`, '', '✦');
820:     burst(shrinePosition(room).x, shrinePosition(room).y, 36, '#8ef2c7', 180);
821:     game.pendingBoon = { reason: 'shrine' };
822:     setTimeout(() => { if (game.mode === 'playing') offerBoons('THE SHRINE ANSWERS'); }, 500);
823:     markSave();
824:     return;
825:   }
826:   if (target.kind === 'portal') descend();
827: }
