858: function applyBoon(id) {
859:   if (game.mode !== 'boon') return;
860:   const boon = BOONS[id];
861:   if (!boon) return;
862:   game.run.boons[id] = (game.run.boons[id] || 0) + 1;
863:   bumpStat(game.save, 'boons');
864:   recalcStats();
865:   if (id === 'ironSkin') game.player.hp = Math.min(game.player.maxHp, game.player.hp + 20);
866:   if (id === 'aetherWell') game.player.aether = Math.min(game.player.maxAether, game.player.aether + 22);
867:   if (id === 'ironSkin' || id === 'aetherWell') { /* max values already raised by recalcStats */ }
868:   game.mode = 'playing';
869:   showEl(UI.boon, false);
870:   game.pendingBoon = null;
871:   toast(`<b>${boon.name}</b> claimed`, '', boon.icon);
872:   game.audio.play('pickup');
873:   updateHud(true);
874:   markSave();
875:   saveNow();
