878: function toRoman(num) {
879:   const map = [[10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']];
880:   let out = '';
881:   for (const [v, s] of map) while (num >= v) { out += s; num -= v; }
882:   return out || 'I';
883: }
