function onKeyDown(event) {
  const blocked = ['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab'];
  if (blocked.includes(event.code)) event.preventDefault();
  if (event.repeat) return;
